147	  @Override
148	  public UnaryOperator<IndexedRecord> projectRecord(Schema from, Schema to, Map<String, String> renamedColumns) {
149	    if (!renamedColumns.isEmpty()) {
150	      throw new UnsupportedOperationException("Schema evolution is not supported for the test reader context");
151	    }
152	    Map<String, Integer> fromFields = IntStream.range(0, from.getFields().size())
153	        .boxed()
154	        .collect(Collectors.toMap(
155	            i -> from.getFields().get(i).name(), i -> i));
156	    Map<String, Integer> toFields = IntStream.range(0, to.getFields().size())
157	        .boxed()
158	        .collect(Collectors.toMap(
159	            i -> to.getFields().get(i).name(), i -> i));
160	
161	    // Check if source schema contains all fields from target schema.
162	    List<Schema.Field> missingFields = to.getFields().stream()
163	        .filter(f -> !fromFields.containsKey(f.name())).collect(Collectors.toList());
164	    if (!missingFields.isEmpty()) {
165	      throw new HoodieException("There are some fields missing in source schema: "
166	          + missingFields);
167	    }
168	
169	    // Build the mapping from source schema to target schema.
170	    Map<Integer, Integer> fieldMap = toFields.entrySet().stream()
171	        .filter(e -> fromFields.containsKey(e.getKey()))
172	        .collect(Collectors.toMap(
173	            e -> fromFields.get(e.getKey()), Map.Entry::getValue));
174	
175	    // Do the transformation.
176	    return record -> {
177	      IndexedRecord outputRecord = new GenericData.Record(to);
178	      for (int i = 0; i < from.getFields().size(); i++) {
179	        if (!fieldMap.containsKey(i)) {
180	          continue;
181	        }
182	        int j = fieldMap.get(i);
183	        outputRecord.put(j, record.get(i));
184	      }
185	      return outputRecord;
186	    };
187	  }
