/**
 * An engine-independent {@link HoodieReaderContext} implementation that operates on Avro
 * {@link IndexedRecord}s. It can be used by any JVM based reader (e.g. the Java engine) that does
 * not have a native columnar record representation to plug into the {@code HoodieFileGroupReader}.
 *
 * <p>Record key extraction depends on the table configuration:
 * <ul>
 *   <li>When {@link HoodieTableConfig#populateMetaFields()} is {@code true}, the key is read from
 *   the {@code _hoodie_record_key} meta field (schema position 2).</li>
 *   <li>Otherwise, the key is derived from the record via a {@link BaseKeyGenerator}, either the one
 *   supplied explicitly or one built automatically from the table configuration.</li>
 * </ul>
 */
public class HoodieAvroReaderContext extends HoodieReaderContext<IndexedRecord> {
  private final HoodieTableConfig tableConfig;
  private final BaseKeyGenerator keyGenerator;

  public HoodieAvroReaderContext(
      StorageConfiguration<?> storageConfiguration,
      HoodieTableConfig tableConfig) {
    this(storageConfiguration, tableConfig,
        tableConfig.populateMetaFields() ? null : buildKeyGenerator(tableConfig));
  }

  public HoodieAvroReaderContext(
      StorageConfiguration<?> storageConfiguration,
      HoodieTableConfig tableConfig,
      BaseKeyGenerator keyGenerator) {
    super(storageConfiguration);
    this.tableConfig = tableConfig;
    this.keyGenerator = keyGenerator;
  }

  private static BaseKeyGenerator buildKeyGenerator(HoodieTableConfig tableConfig) {
    String keyGeneratorClassName = tableConfig.getKeyGeneratorClassName();
    ValidationUtils.checkArgument(keyGeneratorClassName != null,
        "Cannot build a key generator: key generator class name is not set in the table config");
    Object keyGenerator = ReflectionUtils.loadClass(keyGeneratorClassName, tableConfig.getProps());
    ValidationUtils.checkArgument(keyGenerator instanceof BaseKeyGenerator,
        "Key generator " + keyGeneratorClassName + " is not a BaseKeyGenerator");
    return (BaseKeyGenerator) keyGenerator;
  }

  @Override
  public ClosableIterator<IndexedRecord> getFileRecordIterator(
      StoragePath filePath,
      long start,
      long length,
      Schema dataSchema,
      Schema requiredSchema,
      HoodieStorage storage) throws IOException {
    HoodieAvroFileReader reader = (HoodieAvroFileReader) HoodieIOFactory.getIOFactory(storage)
        .getReaderFactory(HoodieRecord.HoodieRecordType.AVRO)
        .getFileReader(new HoodieConfig(), filePath);
    return reader.getIndexedRecordIterator(dataSchema, requiredSchema);
  }

  @Override
  public IndexedRecord convertAvroRecord(IndexedRecord avroRecord) {
    return avroRecord;
  }

  @Override
  public GenericRecord convertToAvroRecord(IndexedRecord record, Schema schema) {
    return (GenericRecord) record;
  }

  @Override
  public Option<HoodieRecordMerger> getRecordMerger(RecordMergeMode mergeMode, String mergeStrategyId, String mergeImplClasses) {
    switch (mergeMode) {
      case EVENT_TIME_ORDERING:
        return Option.of(HoodieAvroRecordMerger.INSTANCE);
      case COMMIT_TIME_ORDERING:
        return Option.of(new OverwriteWithLatestMerger());
      case CUSTOM:
      default:
        if (mergeStrategyId.equals(HoodieRecordMerger.PAYLOAD_BASED_MERGE_STRATEGY_UUID)) {
          return Option.of(HoodieAvroRecordMerger.INSTANCE);
        }
        Option<HoodieRecordMerger> mergerClass =
            HoodieRecordUtils.createValidRecordMerger(EngineType.JAVA, mergeImplClasses, mergeStrategyId);
        if (mergerClass.isEmpty()) {
          throw new IllegalArgumentException("No valid record merger implementation set for merge strategy "
              + mergeStrategyId);
        }
        return mergerClass;
    }
  }

  @Override
  public Object getValue(IndexedRecord record, Schema schema, String fieldName) {
    Schema.Field field = schema.getField(fieldName);
    if (field == null) {
      return null;
    }
    return record.get(field.pos());
  }

  @Override
  public String getRecordKey(IndexedRecord record, Schema schema) {
    if (tableConfig.populateMetaFields()) {
      return getValue(record, schema, RECORD_KEY_METADATA_FIELD).toString();
    }
    return keyGenerator.getRecordKey((GenericRecord) record);
  }

  @Override
  public HoodieRecord<IndexedRecord> constructHoodieRecord(
      Option<IndexedRecord> recordOption,
      Map<String, Object> metadataMap) {
    if (!recordOption.isPresent()) {
      return SpillableMapUtils.generateEmptyPayload(
          (String) metadataMap.get(INTERNAL_META_RECORD_KEY),
          (String) metadataMap.get(INTERNAL_META_PARTITION_PATH),
          (Comparable<?>) metadataMap.get(INTERNAL_META_ORDERING_FIELD),
          tableConfig.getPayloadClass());
    }
    return new HoodieAvroIndexedRecord(recordOption.get());
  }

